function memoize(fn) {
  var cache = {};
  return function (arg) {
    if (Object.prototype.hasOwnProperty.call(cache, arg)) return cache[arg];
    cache[arg] = fn(arg);
    return cache[arg];
  };
}

var calls = 0;
var double = memoize(function (n) { calls++; return n * 2; });
double(2); double(2);
console.log(calls);

